class Solution {
public:
    int stoneGameII(vector<int>& piles) {
        int n = piles.size();
        vector<int> suffix(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) suffix[i] = suffix[i + 1] + piles[i];
        vector<vector<int>> memo(n + 1, vector<int>(n + 1, 0));

        auto dp = [&](auto& self, int i, int m) -> int {
            if (i + 2 * m >= n) return suffix[i];
            if (memo[i][m] != 0) return memo[i][m];

            int res = 0;
            for (int x = 1; x <= 2 * m; ++x) {
                int opp = self(self, i + x, max(m, x));
                res = max(res, suffix[i] - opp);
            }
            return memo[i][m] = res;
        };

        return dp(dp, 0, 1);
    }
};

class Solution {
    int[][] memo;
    int[] suffix;
    int n;

    int dp(int i, int m) {
        if (i + 2 * m >= n) return suffix[i];
        if (memo[i][m] != 0) return memo[i][m];

        int res = 0;
        for (int x = 1; x <= 2 * m; x++) {
            int opp = dp(i + x, Math.max(m, x));
            res = Math.max(res, suffix[i] - opp);
        }
        return memo[i][m] = res;
    }

    public int stoneGameII(int[] piles) {
        n = piles.length;
        suffix = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + piles[i];
        memo = new int[n + 1][n + 1];
        return dp(0, 1);
    }
}

var stoneGameII = function(piles) {
    const n = piles.length;
    const suffix = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + piles[i];
    const memo = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));

    const dp = (i, m) => {
        if (i + 2 * m >= n) return suffix[i];
        if (memo[i][m] !== 0) return memo[i][m];

        let res = 0;
        for (let x = 1; x <= 2 * m; x++) {
            const opp = dp(i + x, Math.max(m, x));
            res = Math.max(res, suffix[i] - opp);
        }
        return memo[i][m] = res;
    };

    return dp(0, 1);
};
